{{-- Show/hide button for a password input. Must sit inside a `relative` wrapper whose x-data defines `show`. --}}
<button type="button" x-on:click="show = !show" class="absolute inset-y-0 right-0 grid w-11 place-items-center rounded-r-md text-slate-400 hover:text-slate-700 focus:outline-none focus-visible:text-primary-700" x-bind:aria-label="show ? 'Ẩn mật khẩu' : 'Hiện mật khẩu'" x-bind:aria-pressed="show.toString()" x-bind:title="show ? 'Ẩn mật khẩu' : 'Hiện mật khẩu'" aria-label="Hiện mật khẩu">
    <svg x-show="!show" class="h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg>
    <svg x-show="show" x-cloak class="h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 3l18 18"/><path d="M10.6 5.1A10.8 10.8 0 0 1 12 5c6.4 0 10 7 10 7a17.6 17.6 0 0 1-3.2 4.2"/><path d="M6.6 6.6C3.9 8.4 2 12 2 12s3.6 7 10 7a10 10 0 0 0 5.4-1.6"/><path d="M9.9 9.9a3 3 0 0 0 4.2 4.2"/></svg>
</button>
